#include <bits/stdc++.h>
#define err(...) {}
#ifdef DEBUG
#include "_debug.cpp"
#include "callable.hpp/callable.hpp"
#endif
#define endl '\n'
using namespace std;
using ll = long long;
constexpr int MAX_N = 10;
string grid[MAX_N];
int scientists_count[MAX_N][MAX_N] = {};
int rescue_count[MAX_N][MAX_N] = {};
int infection_time[MAX_N][MAX_N] = {};
const int dx[4] = {-1, 1, 0, 0};
const int dy[4] = {0, 0, -1, 1};
int shortest_path[MAX_N][MAX_N][MAX_N][MAX_N] = {};
const int MAX_NODES = 2 * MAX_N * MAX_N + 2;
const int BIG_INF = 1'000'000'000;
vector<int> graph[MAX_NODES + 1];
int capacity[MAX_NODES + 1][MAX_NODES + 1], flow[MAX_NODES + 1][MAX_NODES + 1];
int ptr[MAX_NODES + 1], dist[MAX_NODES + 1], parent[MAX_NODES + 1];

bool build_level_graph(int source, int sink) {
    fill(dist, dist + MAX_NODES + 1, -1);
    dist[source] = 0;
    queue<int> bfs;
    bfs.push(source);
    while (!bfs.empty()) {
        int u = bfs.front();
        bfs.pop();
        for (int v : graph[u]) {
            if (capacity[u][v] - flow[u][v] > 0 && dist[v] == -1) {
                dist[v] = dist[u] + 1;
                bfs.push(v);
            }
        }
    }
    return dist[sink] != -1;
}

bool dfs_path(int u, int sink) {
    if (u == sink) return true;
    for (int& idx = ptr[u]; idx < (int)graph[u].size(); ++idx) {
        int v = graph[u][idx];
        if (dist[v] == dist[u] + 1 && capacity[u][v] - flow[u][v] > 0 && dfs_path(v, sink)) {
            parent[v] = u;
            return true;
        }
    }
    return false;
}

bool augmenting_path(int source, int sink) {
    fill(parent, parent + MAX_NODES + 1, -1);
    parent[source] = 0;
    return dfs_path(source, sink);
}

void reset_flow() {
    memset(capacity, 0, sizeof capacity);
    memset(flow, 0, sizeof flow);
}

void connect(int u, int v, int cap) {
    graph[u].push_back(v);
    graph[v].push_back(u);
    capacity[u][v] += cap;
}

int dinic_max_flow(int source, int sink) {
    int total_flow = 0;
    while (build_level_graph(source, sink)) {
        fill(ptr, ptr + MAX_NODES + 1, 0);
        while (augmenting_path(source, sink)) {
            int bottleneck = BIG_INF;
            for (int v = sink, u = parent[v]; v != source; v = u, u = parent[v]) {
                bottleneck = min(bottleneck, capacity[u][v] - flow[u][v]);
            }
            for (int v = sink, u = parent[v]; v != source; v = u, u = parent[v]) {
                flow[u][v] += bottleneck;
                flow[v][u] -= bottleneck;
            }
            total_flow += bottleneck;
        }
    }
    return total_flow;
}

int idx(int size, int r, int c, bool is_right) {
    return r * size + c + (is_right ? size * size : 0);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, limit;
    cin >> n >> limit;
    string buffer;
    pair<int, int> origin;
    for (int i = 0; i < n; ++i) {
        cin >> buffer;
        for (int j = 0; j < n; ++j) {
            if (buffer[j] == 'Y') {
                grid[i][j] = 'Y';
            } else if (buffer[j] == 'Z') {
                grid[i][j] = 'Z';
                origin = {i, j};
            } else {
                grid[i][j] = '.';
                scientists_count[i][j] += buffer[j] - '0';
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        cin >> buffer;
        for (int j = 0; j < n; ++j) {
            if (buffer[j] != 'Y' && buffer[j] != 'Z') {
                rescue_count[i][j] += buffer[j] - '0';
            }
        }
    }
    memset(infection_time, -1, sizeof infection_time);
    infection_time[origin.first][origin.second] = 0;
    queue<pair<int, int>> q;
    q.push(origin);
    while (!q.empty()) {
        int x = q.front().first, y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dx[k], ny = y + dy[k];
            if (0 <= nx && nx < n && 0 <= ny && ny < n && grid[nx][ny] == '.' && infection_time[nx][ny] == -1) {
                infection_time[nx][ny] = infection_time[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
    memset(shortest_path, -1, sizeof shortest_path);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == '.') {
                shortest_path[i][j][i][j] = 0;
                queue<pair<int, int>> bfs;
                bfs.push({i, j});
                while (!bfs.empty()) {
                    int r = bfs.front().first, c = bfs.front().second;
                    bfs.pop();
                    if (infection_time[r][c] == -1 || shortest_path[i][j][r][c] < infection_time[r][c]) {
                        for (int k = 0; k < 4; ++k) {
                            int nr = r + dx[k], nc = c + dy[k];
                            if (0 <= nr && nr < n && 0 <= nc && nc < n && grid[nr][nc] == '.' &&
                                (infection_time[nr][nc] == -1 || shortest_path[i][j][r][c] + 1 <= infection_time[nr][nc]) &&
                                shortest_path[i][j][nr][nc] == -1) {
                                shortest_path[i][j][nr][nc] = shortest_path[i][j][r][c] + 1;
                                bfs.push({nr, nc});
                            }
                        }
                    }
                }
            }
        }
    }
    int source = 2 * n * n, target = 2 * n * n + 1;
    reset_flow();
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (scientists_count[i][j]) {
                connect(source, idx(n, i, j, false), scientists_count[i][j]);
            }
            if (rescue_count[i][j]) {
                connect(idx(n, i, j, true), target, rescue_count[i][j]);
            }
            for (int ri = 0; ri < n; ++ri) {
                for (int rj = 0; rj < n; ++rj) {
                    if (shortest_path[i][j][ri][rj] != -1 && shortest_path[i][j][ri][rj] <= limit) {
                        connect(idx(n, i, j, false), idx(n, ri, rj, true), BIG_INF);
                    }
                }
            }
        }
    }
    cout << dinic_max_flow(source, target) << endl;
    return 0;
}
